// ../../interchange/packages/hub-api/src/routes/principals.ts
function formatPrincipal(row, roles3, identity) {
  return {
    id: row.id,
    tenantId: row.tenantId,
    kind: row.kind,
    refId: row.refId,
    displayName: identity?.displayName ?? row.refId,
    ...identity?.email ? { email: identity.email } : {},
    status: row.status,
    roles: roles3,
    createdAt: ts(row.createdAt),
    updatedAt: ts(row.updatedAt)
  };
}
async function resolveIdentities(db2, principals3) {
  const identities = new Map;
  const userRefIds = principals3.filter((p) => p.kind === "user").map((p) => p.refId);
  const agentRefIds = principals3.filter((p) => p.kind === "agent").map((p) => p.refId);
  if (userRefIds.length > 0) {
    const users = await db2.query.user.findMany({
      where: (u, { inArray: inArray2 }) => inArray2(u.id, userRefIds)
    });
    for (const u of users) {
      identities.set(u.id, { displayName: u.name, email: u.email });
    }
  }
  if (agentRefIds.length > 0) {
    const agents3 = await db2.query.agent.findMany({
      where: (a, { inArray: inArray2 }) => inArray2(a.id, agentRefIds)
    });
    for (const a of agents3) {
      identities.set(a.id, { displayName: a.name });
    }
    const unresolvedRefIds = agentRefIds.filter((id2) => !identities.has(id2));
    if (unresolvedRefIds.length > 0) {
      const instances2 = await db2.query.agentInstance.findMany({
        where: (i, { inArray: inArray2 }) => inArray2(i.id, unresolvedRefIds)
      });
      const definitionIds = [...new Set(instances2.map((i) => i.agentId))];
      const definitions = definitionIds.length > 0 ? await db2.query.agent.findMany({
        where: (a, { inArray: inArray2 }) => inArray2(a.id, definitionIds)
      }) : [];
      const defNames = new Map(definitions.map((d) => [d.id, d.name]));
      for (const inst of instances2) {
        const name = defNames.get(inst.agentId);
        if (name) {
          identities.set(inst.id, { displayName: `${name} (instance)` });
        }
      }
    }
  }
  return identities;
}
async function loadRolesForPrincipal(db2, principalId) {
  const assignments = await db2.query.principalRole.findMany({
    where: eq(principalRole.principalId, principalId)
  });
  if (assignments.length === 0)
    return [];
  const roleIds = assignments.map((a) => a.roleId);
  const roles3 = await db2.query.role.findMany({
    where: (r, { inArray: inArray2 }) => inArray2(r.id, roleIds)
  });
  return roles3.map((r) => ({ id: r.id, name: r.name }));
}
