// src/db/schema.ts
var sessionStatus = ["analyzing", "reviewing", "generating", "improving", "exporting", "done"];
var severity = ["low", "medium", "high", "critical"];
var collateralType = ["email", "linkedin", "one-pager", "battlecard"];
var collateralStatus = ["draft", "approved", "rejected"];
var transcriptSource = ["paste", "granola"];
var transcript = pgTable("transcript", {
  id: uuid2("id").primaryKey().defaultRandom(),
  content: text("content").notNull(),
  source: text("source", { enum: transcriptSource }).notNull().default("paste"),
  createdAt: timestamp("created_at").notNull().defaultNow()
});
var workbenchSession = pgTable("workbench_session", {
  id: uuid2("id").primaryKey().defaultRandom(),
  transcriptId: uuid2("transcript_id").notNull().references(() => transcript.id, { onDelete: "cascade" }),
  status: text("status", { enum: sessionStatus }).notNull().default("analyzing"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow().$onUpdate(() => new Date)
});
var painPoint = pgTable("pain_point", {
  id: uuid2("id").primaryKey().defaultRandom(),
  sessionId: uuid2("session_id").notNull().references(() => workbenchSession.id, { onDelete: "cascade" }),
  severity: text("severity", { enum: severity }).notNull(),
  context: text("context").notNull(),
  quote: text("quote").notNull(),
  selected: boolean("selected").notNull().default(false),
  createdAt: timestamp("created_at").notNull().defaultNow()
});
var collateralItem = pgTable("collateral_item", {
  id: uuid2("id").primaryKey().defaultRandom(),
  painPointId: uuid2("pain_point_id").notNull().references(() => painPoint.id, { onDelete: "cascade" }),
  type: text("type", { enum: collateralType }).notNull(),
  title: text("title").notNull(),
  body: text("body").notNull(),
  status: text("status", { enum: collateralStatus }).notNull().default("draft"),
  version: integer2("version").notNull().default(1),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow().$onUpdate(() => new Date)
});
var collateralVersion = pgTable("collateral_version", {
  id: uuid2("id").primaryKey().defaultRandom(),
  collateralId: uuid2("collateral_id").notNull().references(() => collateralItem.id, { onDelete: "cascade" }),
  title: text("title").notNull(),
  body: text("body").notNull(),
  version: integer2("version").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow()
});

// src/lib/granola.ts
class GranolaClient {
  apiKey;
  apiUrl;
  constructor() {
    this.apiKey = process.env.GRANOLA_API_KEY || "";
    this.apiUrl = process.env.GRANOLA_API_URL || "";
    if (!this.apiKey) {
      throw new Error("GRANOLA_API_KEY is not configured");
    }
    if (!this.apiUrl) {
      throw new Error("GRANOLA_API_URL is not configured");
    }
  }
  async getRecentNotes(limit = 3) {
    const url2 = new URL(`${this.apiUrl}/v1/notes`);
    url2.searchParams.append("limit", limit.toString());
    const response = await fetch(url2.toString(), {
      headers: {
        Authorization: `Bearer ${this.apiKey}`,
        "Content-Type": "application/json"
      }
    });
    if (!response.ok) {
      throw new Error(`Granola API error: ${response.status} ${response.statusText}`);
    }
    const data = await response.json();
    return data.data || [];
  }
  async getNoteWithTranscript(noteId) {
    const url2 = new URL(`${this.apiUrl}/v1/notes/${noteId}`);
    url2.searchParams.append("include", "transcript");
    const response = await fetch(url2.toString(), {
      headers: {
        Authorization: `Bearer ${this.apiKey}`,
        "Content-Type": "application/json"
      }
    });
    if (!response.ok) {
      throw new Error(`Granola API error: ${response.status} ${response.statusText}`);
    }
    const data = await response.json();
    return data.data;
  }
}

// src/routes/intake.ts
var log10 = getLogger(["api", "intake"]);
function createIntakeRouter(db2) {
  const router2 = new Hono2;
  let granolaClient = null;
  try {
    granolaClient = new GranolaClient;
  } catch {}
  router2.post("/intake", async (c) => {
    try {
      const body = await c.req.json();
      if (!body.source || !["paste", "granola"].includes(body.source)) {
        return c.json({ error: "Invalid source" }, 400);
      }
      let transcriptContent;
      if (body.source === "paste") {
        if (!body.transcript) {
          return c.json({ error: "transcript is required for paste source" }, 400);
        }
        if (body.transcript.trim().length === 0) {
          return c.json({ error: "transcript cannot be empty" }, 400);
        }
        if (body.transcript.length > 500000) {
          return c.json({ error: "transcript exceeds maximum length (500k characters)" }, 413);
        }
        transcriptContent = body.transcript;
      } else if (body.source === "granola") {
        if (!body.granolaId) {
          return c.json({ error: "granolaId is required for granola source" }, 400);
        }
        if (!granolaClient) {
          return c.json({ error: "Granola API not configured" }, 503);
        }
        try {
          const note = await granolaClient.getNoteWithTranscript(body.granolaId);
          transcriptContent = note.transcript || note.title || "";
          if (!transcriptContent) {
            return c.json({ error: "Could not retrieve transcript from Granola" }, 400);
          }
        } catch (error53) {
          return c.json({ error: "Failed to fetch from Granola API" }, 400);
        }
      } else {
        return c.json({ error: "Invalid source" }, 400);
      }
      const [transcriptRow] = await db2.insert(transcript).values({
        content: transcriptContent,
        source: body.source
      }).returning();
      if (!transcriptRow) {
        return c.json({ error: "Failed to create transcript" }, 500);
      }
      const [sessionRow] = await db2.insert(workbenchSession).values({
        transcriptId: transcriptRow.id,
        status: "analyzing"
      }).returning();
      if (!sessionRow) {
        return c.json({ error: "Failed to create session" }, 500);
      }
      const response = {
        sessionId: sessionRow.id,
        transcriptId: transcriptRow.id,
        status: sessionRow.status
      };
      return c.json(response, 200);
    } catch (error53) {
      log10.error("Intake error");
      return c.json({ error: "Internal server error" }, 500);
    }
  });
  router2.get("/recent-calls", async (c) => {
    try {
      if (!granolaClient) {
        return c.json({ error: "Granola API not configured" }, 503);
      }
      const calls = await granolaClient.getRecentNotes(3);
      return c.json({ calls });
    } catch (error53) {
      log10.error("Recent calls error");
      return c.json({ error: "Failed to fetch recent calls" }, 500);
    }
  });
  return router2;
}

// src/routes/analyze.ts
function createAnalyzeHandler(db2) {
  const app = new Hono2;
  app.post("/analyze", async (c) => {
    return c.json({ sessionId: "todo", painPoints: [], status: "analyzing" });
  });
  return app;
}

